/// One byte offset at which a literal match begins.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct LiteralMatch {
    pub offset: u64,
}

/// The bounded result of scanning a chunked byte stream.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct LiteralSearchResult {
    pub matches: Vec<LiteralMatch>,
    pub truncated: bool,
    pub bytes_scanned: u64,
}

/// Failures that can be determined without interpreting bytes as text.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum LiteralSearchError {
    EmptyNeedle,
    ZeroMatchLimit,
    OffsetOverflow,
}

fn prefix_table(needle: &[u8]) -> Vec<usize> {
    let mut table = vec![0; needle.len()];
    let mut prefix_len = 0;

    for index in 1..needle.len() {
        while prefix_len > 0 && needle[index] != needle[prefix_len] {
            prefix_len = table[prefix_len - 1];
        }
        if needle[index] == needle[prefix_len] {
            prefix_len += 1;
        }
        table[index] = prefix_len;
    }

    table
}

/// Finds a literal byte sequence in the logical concatenation of `chunks`.
///
/// Matches may cross chunk boundaries and may overlap. Only the requested
/// number of offsets is retained.
///
/// # Errors
///
/// Returns [`LiteralSearchError::EmptyNeedle`] or
/// [`LiteralSearchError::ZeroMatchLimit`] before consuming `chunks`. Returns
/// [`LiteralSearchError::OffsetOverflow`] if the scanned byte count cannot fit
/// in a `u64`.
pub fn search_literal_chunks<'a, I>(
    chunks: I,
    needle: &[u8],
    max_matches: usize,
) -> Result<LiteralSearchResult, LiteralSearchError>
where
    I: IntoIterator<Item = &'a [u8]>,
{
    if needle.is_empty() {
        return Err(LiteralSearchError::EmptyNeedle);
    }
    if max_matches == 0 {
        return Err(LiteralSearchError::ZeroMatchLimit);
    }

    let needle_len = u64::try_from(needle.len()).map_err(|_| LiteralSearchError::OffsetOverflow)?;
    let table = prefix_table(needle);
    let mut matches = Vec::new();
    let mut bytes_scanned = 0_u64;
    let mut automaton_state = 0_usize;

    for chunk in chunks {
        for &byte in chunk {
            let next_bytes_scanned = bytes_scanned
                .checked_add(1)
                .ok_or(LiteralSearchError::OffsetOverflow)?;

            while automaton_state > 0 && needle[automaton_state] != byte {
                automaton_state = table[automaton_state - 1];
            }
            if needle[automaton_state] == byte {
                automaton_state += 1;
            }

            if automaton_state == needle.len() {
                let offset = next_bytes_scanned
                    .checked_sub(needle_len)
                    .ok_or(LiteralSearchError::OffsetOverflow)?;
                if matches.len() == max_matches {
                    return Ok(LiteralSearchResult {
                        matches,
                        truncated: true,
                        bytes_scanned: next_bytes_scanned,
                    });
                }
                matches.push(LiteralMatch { offset });
                automaton_state = table[automaton_state - 1];
            }

            bytes_scanned = next_bytes_scanned;
        }
    }

    Ok(LiteralSearchResult {
        matches,
        truncated: false,
        bytes_scanned,
    })
}
